mapper.select:
select *
from t_showing

  
    and audit_status=#{auditStatus}
  
  
    and cinema_id=#{cinemaId}
  
  
    and movie_id=#{movieId}
  

order by id desc

select *
from t_showing
where cinema_id=#{cinemaId}
  and audit_status=1
  
    and movie_id=#{movieId}
  
order by start_time asc

select s.id, s.cinema_id as cinemaId, c.name as cinemaName, s.hall_id as hallId, h.name as hallName, s.movie_id as movieId, m.name as movieName, m.poster_url as moviePosterUrl, s.start_time as startTime, s.end_time as endTime, s.ticket_price as ticketPrice, s.audit_status as auditStatus from t_showing s join t_cinema c on c.id = s.cinema_id join t_hall h on h.id = s.hall_id join t_movie m on m.id = s.movie_id where s.cinema_id=#{cinemaId} and s.audit_status=1
and s.movie_id=#{movieId}
order by s.start_time asc

select * from t_showing
where hall_id=#{hallId}
  and start_time < #{endTime}
  and end_time > #{startTime}

  and id != #{excludeId}

mapper.update:
update t_showing
set audit_status=#{auditStatus}, audited_by_admin_id=#{adminId}, audited_time=now(), audit_reason=#{reason}
where id=#{id}
